import {BEATS, BrickAudio} from './audio.js';

/* /chimpanzee BRICKS — Edition 03. Brick-built controls with real WebSocket state and original synchronized beats. */
const $=q=>document.querySelector(q);
const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatTime=t=>{t=Math.max(0,Math.floor(Number(t)||0));return `${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`};
const nfmt=n=>new Intl.NumberFormat('en-US').format(n);
const key='chimpanzee.bricks.v3';
let persisted={};try{persisted=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const isServed=location.protocol.startsWith('http')&&!/github\.io|vercel\.app|netlify\.app|pages\.dev/.test(location.hostname);
const defaultUrl=isServed?(location.protocol==='https:'?'wss://':'ws://')+location.host+'/socket':'';
const state={theme:persisted.theme==='paper'?'paper':'slate',name:persisted.name||'Builder',serverUrl:persisted.serverUrl||defaultUrl,view:'home',filter:'All sounds',room:null,identity:null,role:null,socket:null,connecting:false,modal:null,clockOffset:0,connected:false,soundEnabled:false,solo:{track:null,playing:false,at:Date.now(),offsetMs:0},localFiles:[],localTrackId:null,localAudio:null,localBlobUrl:null,soloFavorites:new Set(persisted.favorites||[]),introDone:false,joinPin:'',lastError:'',lastSnapshot:null};
const engine=new BrickAudio();engine.onStatus=()=>{state.soundEnabled=engine.enabled;renderDock()};
const save=()=>localStorage.setItem(key,JSON.stringify({theme:state.theme,name:state.name,serverUrl:state.serverUrl,favorites:[...state.soloFavorites]}));
const btn=(action,label,cls='brick-btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const ibtn=(action,ic,label,cls='icon-btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra}>${icon(ic)}</button>`;
const art=(shade='peach',round=false,record=false,playing=false)=>`<div class="album-art shade-${esc(shade)} ${record?'record':''}">${record?`<div class="record-disc ${playing?'playing':''}"></div>`:`<span class="cover-brick one"></span><span class="cover-brick two"></span><span class="cover-brick three"></span><span class="cover-symbol">/c.</span><span class="cover-glint"></span>`}</div>`;
const beatOf=t=>BEATS.find(b=>b.id===(typeof t==='string'?t:t?.beat))||null;
const trackMeta=t=>{if(!t)return null;if(t.kind==='beat'){const b=beatOf(t);return b?{...b,title:t.title||b.title,artist:b.artist}:null}return{shade:t.kind==='youtube'?'violet':'mint',title:t.title||'Audio link',artist:t.artist||'Shared link',accent:'#ae9efe',duration:180}};
const section=(title,desc='',action='')=>`<div class="section-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;
const empty=(emoji,title,sub)=>`<div class="empty-state"><div class="empty-icon">${emoji}</div><h3>${title}</h3><p>${sub}</p></div>`;
const hasRights=()=>state.role==='host'||state.role==='admin';
const selected=()=>state.room?.queue.find(t=>t.id===state.room?.playback?.trackId)||null;
const roomPlayback=()=>state.room?.playback||null;
const roomPlaying=()=>Boolean(roomPlayback()?.playing);
const serverNow=()=>Date.now()+state.clockOffset;
const positionMs=()=>{const p=roomPlayback();return p?Math.max(0,p.offsetMs+(p.playing?serverNow()-p.at:0)):0};
const soloPosition=()=>Math.max(0,state.solo.offsetMs+(state.solo.playing?Date.now()-state.solo.at:0));

function navItem(view,label,ic,mobile=false){return mobile?`<button class="bottom-item ${state.view===view?'active':''}" data-action="navigate" data-view="${view}" aria-label="${label}">${icon(ic)}<span>${label}</span></button>`:`<button class="nav-link ${state.view===view?'active':''}" data-action="navigate" data-view="${view}"><span class="nav-glyph">${icon(ic)}</span><span class="nav-label">${label}</span></button>`}
function header(){
 $('#sidebar').innerHTML=`<a class="brand" href="#home" data-action="navigate" data-view="home"><span class="brand-mark">/</span><div><div class="brand-word"><span>/</span>chimpanzee</div><div class="brand-edition">BRICKS · 03</div></div></a><div><p class="sidebar-label">YOUR PLAYGROUND</p><div class="side-links">${navItem('home','Home','house')}${navItem('lab','Sound lab','music')}${navItem('queue','The queue','queue')}${navItem('crew','Your crew','users')}${navItem('crate','My crate','grid')}</div></div><div class="sidebar-bottom"><div class="sidebar-promo"><div class="studs-mini"></div><strong>Good music is built together.</strong><p>Start a room. Stack sounds. Make something yours.</p><span class="promo-tag">EDITION 03 — BRICKS</span></div><div class="side-links" style="margin-top:15px">${navItem('settings','Settings','settings')}</div></div>`;
 $('#bottomNav').innerHTML=`${navItem('home','Home','house',true)}${navItem('lab','Lab','music',true)}${navItem('queue','Queue','queue',true)}${navItem('crew','Crew','users',true)}${navItem('crate','Crate','grid',true)}`;
 const headline={home:state.room?'YOUR LIVE STATION':'BUILD SOMETHING GOOD',lab:'ORIGINAL SOUNDS',queue:'YOUR SOUND STACK',crew:'BETTER TOGETHER',crate:'LOCAL MUSIC',settings:'YOUR SETTINGS'}[state.view];
 $('#topbar').innerHTML=`<div class="top-left"><span class="bread">/chimpanzee &nbsp;/&nbsp; <strong>${headline}</strong></span></div><div class="top-right">${state.room?`<div class="online-chip"><span class="status-dot"></span>${state.room.members.length} CONNECTED</div><div class="live-chip"><span class="status-dot"></span> LIVE ROOM</div>`:`<div class="live-chip"><span class="status-dot"></span> BRICK EDITION</div>`}<button class="top-avatar" aria-label="Settings" title="Settings" data-action="navigate" data-view="settings">${esc(state.name[0]||'B').toUpperCase()}</button></div>`;
 $('#themeCorner').innerHTML=`${btn('theme',`<span class="theme-stud"></span>${state.theme==='slate'?'Paper':'Slate'}`,'theme-switch')}`;
 document.body.dataset.theme=state.theme;
}
function render(){
 const active=document.activeElement;const activeId=active?.id;const focusInfo=activeId&&/^(chatText|linkTitle|linkUrl|joinName|joinPin|hostName|hostRoom|folderUrl|folderTitle|settingsUrl|settingsName)$/.test(activeId)?{id:activeId,value:active.value,start:active.selectionStart,end:active.selectionEnd}:null;
 header();
 let markup='';
 switch(state.view){case 'home':markup=state.room?roomHome():welcomeHome();break;case 'lab':markup=labView();break;case 'queue':markup=queueView();break;case 'crew':markup=crewView();break;case 'crate':markup=crateView();break;case 'settings':markup=settingsView();break;default:markup=welcomeHome()}
 $('#stage').innerHTML=markup;
 if(focusInfo){const el=document.getElementById(focusInfo.id);if(el){el.value=focusInfo.value;el.focus({preventScroll:true});try{el.setSelectionRange(focusInfo.start,focusInfo.end)}catch{}}}
 renderDock();renderModal();updateProgress();
}
function navigate(view){if(!['home','lab','queue','crew','crate','settings'].includes(view))return;state.view=view;$('#stage').classList.remove('page-changing');void $('#stage').offsetWidth;$('#stage').classList.add('page-changing');render();window.scrollTo({top:0,behavior:'smooth'})}
function quickImportShelf(){
 const recent=state.localFiles.slice(0,3);
 return `<section class="panel home-local-shelf" aria-label="Music on this device">
   <div class="local-shelf-visual" aria-hidden="true"><span class="shelf-stud stud-1"></span><span class="shelf-stud stud-2"></span><span class="shelf-stud stud-3"></span><span class="shelf-note">♫</span></div>
   <div class="local-shelf-content"><div class="overline">YOUR SONGS · YOUR DEVICE</div><h2>Bring your own beats.</h2><p>Choose MP3, M4A, WAV or other supported audio files from your phone. They'll be saved for offline listening.</p><div class="local-shelf-actions">
   ${btn('import-files',`${icon('upload')} Add music from device`,'brick-btn local-import-primary')}
   ${btn('navigate',`My crate ${state.localFiles.length?'('+state.localFiles.length+')':''} ${icon('arrow')}`,'brick-btn secondary','data-view="crate"')}
   </div>
   <p class="local-shelf-note">${state.room?'Private listening: imported files are not broadcast to station listeners.':'Stored privately on this device. Nothing is uploaded to a server.'}</p>
   ${recent.length?`<div class="local-shelf-recent">${recent.map(f=>`<button type="button" class="local-shelf-track" data-action="local-play" data-id="${esc(f.id)}" aria-label="Play ${esc(f.name)} on this device"><span class="local-mini-note">♫</span><span class="local-mini-title">${esc(f.name)}</span><span class="local-mini-play">${icon('play')}</span></button>`).join('')}</div>`:''}
   </div></section>`;
}
function welcomeHome(){return `
  <div class="overline">Your bricks. Your beats. Your people.</div>
  <h1 class="page-title">Build the beat <span style="color:var(--coral)">together.</span></h1>
  <p class="page-sub">The social listening playground where every song is a brick in your story. Create a station, invite your crew, and let the good stuff click.</p>
  <div class="welcome-grid" style="margin-top:28px">
    <div class="welcome-hero"><span class="hero-badge">LET'S MAKE SOME NOISE</span><h2 class="hero-title">One station.<br>Infinite <em>vibes.</em></h2><p class="hero-copy">Your own room, a rotating PIN, shared controls and music made of pure imagination. Zero music subscriptions required to try our original brick beats.</p><div class="hero-actions">${btn('open-host',`${icon('plus')} Create a station`)}${btn('import-files',`${icon('upload')} Add music from device`,'brick-btn sun')}${btn('navigate',`Explore sounds ${icon('arrow')}`,'brick-btn secondary','data-view="lab"')}</div><div class="hero-sculpture"><div class="sculpture-base"></div><div class="sculpture-mid"></div><div class="sculpture-top"></div></div></div>
    <div class="panel join-panel"><div class="overline">HAVE A PIN?</div><h2 class="join-title">Jump right in.</h2><p class="join-desc">Someone's already hosting? Four little numbers and you're in the crew.</p><form id="joinForm"><label class="input-label" for="joinName">Your nickname</label><input class="field" id="joinName" name="name" autocomplete="nickname" maxlength="25" value="${esc(state.name)}" placeholder="e.g. Space Monkey" required><label class="input-label" for="joinPin">Station PIN</label><input class="field pin-input" id="joinPin" name="pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="••••" value="${esc(state.joinPin)}" required><button class="brick-btn sun join-join" type="submit">Join the station ${icon('arrow')}</button></form><div class="division">OR</div>${btn('navigate',`Try the Sound Lab ${icon('music')}`,'brick-btn secondary join-join','data-view="lab"')}<div class="join-foot">Built with ❤️ and satisfying little studs.</div></div>
  </div>
  <div class="metric-strip"><div class="panel metric"><div class="metric-icon coral">01</div><div><strong>Live rooms</strong><span>Make a station in a tap</span></div></div><div class="panel metric"><div class="metric-icon sun">02</div><div><strong>Brick beats</strong><span>Original sounds, ready to play</span></div></div><div class="panel metric"><div class="metric-icon mint">03</div><div><strong>Your crew</strong><span>Real chat & shared queue</span></div></div></div>
  ${quickImportShelf()}
  ${section('Fresh out of the Sound Lab','Hand-built tracks that sound better together.',`<button class="small-action" data-action="navigate" data-view="lab">Explore all ${icon('arrow')}</button>`)}
  <div class="card-grid">${BEATS.slice(0,3).map(beatCard).join('')}</div>`}
function beatCard(b){return `<article class="panel beat-card" data-beat="${b.id}"><div class="album-wrap">${art(b.shade)}<button class="card-play" data-action="solo-beat" data-beat="${b.id}" title="Play ${esc(b.title)}" aria-label="Play ${esc(b.title)}">${icon('play')}</button></div><div class="beat-caption"><div class="beat-row"><div><h3>${esc(b.title)}</h3><p>${esc(b.mood)} · ${b.bpm} BPM</p></div><button class="beat-fav ${state.soloFavorites.has(b.id)?'active':''}" aria-label="Favorite ${esc(b.title)}" data-action="favorite" data-beat="${b.id}">${icon('heart')}</button></div><div class="beat-meta"><span class="beat-pill">${esc(b.key)} · ORIGINAL</span><span style="font-size:11px;color:var(--muted)">${formatTime(b.duration)}</span></div></div><div class="lab-track-actions">${btn('solo-beat',`${icon('play')} Play`,'brick-btn small lab-play-button',`data-beat="${b.id}"`)}${state.room?btn('add-beat',`${icon('plus')} Queue`,'brick-btn small secondary',`data-beat="${b.id}" ${!hasRights()?'disabled':''}`):btn('open-host',`${icon('plus')} Room`,'brick-btn small secondary')}</div></article>`}
function labView(){const beats=state.filter==='Favorites'?BEATS.filter(b=>state.soloFavorites.has(b.id)):state.filter==='Chill'?BEATS.filter(b=>b.bpm<=108):state.filter==='Energy'?BEATS.filter(b=>b.bpm>108):BEATS;return `<div class="overline">/chimpanzee originals</div><h1 class="page-title">The Sound Lab.</h1><p class="page-sub">Six original tracks built from code and imagination. Generated live, not copied or streamed. Pick one for yourself or add it to the room.</p><div class="lab-banner" style="margin-top:25px"><div><div class="hero-badge">HANDCRAFTED DIGITAL SOUND</div><h2>Every great vibe<br>starts with a brick.</h2><p>100% original procedural beats. Each note is made in your device's audio engine — and the station's timing is shared with your crew.</p></div><div class="lab-visual"><span class="lab-piece a"></span><span class="lab-piece b"></span><span class="lab-piece c"></span></div></div><div class="filter-row">${['All sounds','Chill','Energy','Favorites'].map(x=>`<button class="filter-btn ${state.filter===x?'active':''}" data-action="filter" data-filter="${esc(x)}">${esc(x)}</button>`).join('')}</div>${beats.length?`<div class="card-grid">${beats.map(beatCard).join('')}</div>`:empty('♡','No favorites yet','Tap a heart on any track to save it for later.')}`}
function currentArtwork(t,playing=false){const meta=trackMeta(t);return art(meta?.shade||'violet',false,t?.kind==='beat',playing)}
function playbackButtons(t){if(!t)return '';const playing=roomPlaying(),can=hasRights();return `<div class="station-controls">${ibtn('prev','back','Previous track','transport',can?'':'disabled') }<button class="play-main" data-action="toggle-room" aria-label="${playing?'Pause':'Play'}" ${can?'':'disabled'}>${icon(playing?'pause':'play')}</button>${ibtn('next','skip','Next track','transport',can?'':'disabled')}</div>`}
function roomHome(){const t=selected(),meta=trackMeta(t),room=state.room;return `
  <div class="station-header"><div><div class="overline">${esc(room.name)} · ${esc(state.role)}</div><h1 class="page-title">The Brickroom <span style="color:var(--coral)">is live.</span></h1><p class="page-sub">Stack sounds and watch the whole crew light up.</p><div class="station-import-actions">${btn('import-files',`${icon('upload')} Add music from device`,'brick-btn small secondary')}<span>Private to your phone · not broadcast to listeners</span></div></div><div class="soft-pill coral"><span class="status-dot"></span>${room.members.length} ${room.members.length===1?'PERSON':'PEOPLE'} CONNECTED</div></div>
  <div class="station-grid"><div class="panel station-player">${t?`<div class="player-label">${roomPlaying()?'✳ NOW BUILDING':'READY TO PLAY'} · ${t.kind==='beat'?'ORIGINAL BEAT':t.kind==='youtube'?'OFFICIAL YOUTUBE':'EXTERNAL AUDIO'}</div><div class="station-art">${currentArtwork(t,roomPlaying())}</div><canvas class="station-visualizer" id="visualizer" aria-label="Sound-responsive bars"></canvas><div class="station-track"><h2>${esc(meta?.title||'Unknown track')}</h2><p>${esc(meta?.artist||'Shared audio')} ${t.kind==='beat'?'· '+beatOf(t)?.bpm+' BPM':''}</p></div>${t.kind==='youtube'?`<div class="notice"><strong>Official YouTube playback.</strong> Videos open in a visible, authorized player. Playback is controlled separately by each viewer.</div><div style="display:flex;justify-content:center;margin-top:16px">${btn('open-video',`Open official player ${icon('arrow')}`,'brick-btn')}</div>`:playbackButtons(t)}<div class="progress"><span data-elapsed>${formatTime(positionMs()/1000)}</span><div class="progress-track"><div class="progress-fill" data-progress></div></div><span>${t.kind==='beat'?'∞':formatTime(meta?.duration)}</span></div><div class="volume-row">${icon('volume')}<input class="slider" type="range" id="volume" min="0" max="100" value="${Math.round(engine.level*100)}" aria-label="Volume"><span id="volumeLabel">${Math.round(engine.level*100)}%</span></div>${!state.soundEnabled?`<div style="text-align:center;margin-top:14px">${btn('enable-audio',`Tap to enable sound ${icon('volume')}`,'brick-btn sun small')}</div>`:''}`: `<div class="no-track"><div class="empty-art"><span class="toy"></span></div><h3>Nothing on the deck. Yet.</h3><p>Open the Sound Lab and place the first beat into your shared queue.</p>${hasRights()?btn('navigate',`Find a sound ${icon('arrow')}`,'brick-btn','data-view="lab"'):''}</div>`}</div>
    <div><div class="panel pin-card"><div class="pin-head"><div><h3>Station access PIN</h3><p>${state.role==='host'?'Share these four bricks to invite friends.':'Share with a friend to join this room.'}</p></div>${ibtn('copy-pin','link','Copy PIN')}</div><div class="pin-row">${String(room.pin||'----').padStart(4,'-').slice(0,4).split('').map(n=>`<div class="pin-digit">${esc(n)}</div>`).join('')}</div><div class="pin-footer"><span class="pin-message"><span class="status-dot" style="color:var(--mint)"></span> RESETS IN <span id="pinSeconds">${Math.max(0,Math.ceil((room.pinExpires-serverNow())/1000))}s</span></span><div class="tiny-progress"><span id="pinProgress"></span></div></div></div>
    <div class="panel room-queue"><div class="room-queue-head"><h3>Up next <span style="color:var(--muted)">(${room.queue.length})</span></h3><button class="small-action" data-action="navigate" data-view="queue">View all ${icon('arrow')}</button></div>${room.queue.length?`<div class="queue-list">${room.queue.slice(0,5).map((q,i)=>queueItem(q,i,true)).join('')}</div>`:`<div class="room-empty">Your queue is a blank canvas.<br>Add a beat and watch it build.</div>`}<p class="queue-small">${hasRights()?'As host or admin, you can control the shared queue.':'Ask your host for admin access to control the queue.'}</p></div>
    <div style="display:flex;gap:10px;margin-top:14px">${btn('navigate',`${icon('users')} Crew & chat`,'brick-btn secondary','data-view="crew"')}${state.role==='host'?btn('open-end',`End room`,'brick-btn ghost'):''}</div>
    </div>
  </div>`}
function queueItem(q,i,small=false){const meta=trackMeta(q),isActive=q.id===state.room?.playback?.trackId;return `<div class="queue-item ${isActive?'active':''}"><span class="queue-index">${isActive?'♫':String(i+1).padStart(2,'0')}</span><div class="album-round">${art(meta?.shade||'violet')}</div><div class="queue-info"><strong>${esc(meta?.title||q.title)}</strong><small>${esc(meta?.artist||q.kind)} · ${q.kind==='beat'?'GENERATED':q.kind.toUpperCase()}</small></div>${hasRights()?`${ibtn('select-track','play','Play this track','queue-action',`data-id="${esc(q.id)}"`)}${small?'':`${ibtn('queue-up','arrow','Move up','queue-action',`data-id="${esc(q.id)}"`)}${ibtn('queue-down','arrow','Move down','queue-action',`data-id="${esc(q.id)}"`)}${ibtn('queue-remove','close','Remove track','queue-action',`data-id="${esc(q.id)}"`)}`}`:''}</div>`}
function queueView(){const r=state.room;return `<div class="overline">Arrange your soundtrack</div><h1 class="page-title">The Queue.</h1><p class="page-sub">Every brick has its place. Add original beats, authorized direct audio links, or YouTube links for playback in its official player.</p><div class="two-col" style="margin-top:28px"><section class="panel content-panel">${section('The sound stack',r?`${r.queue.length} brick${r.queue.length===1?'':'s'} in your station`:'Create or join a station to build a shared queue.')}${r?(r.queue.length?`<div class="queue-list">${r.queue.map((q,i)=>queueItem(q,i)).join('')}</div>`:empty('🧱','An empty stack','Add a track from the Sound Lab to kick things off.')):empty('🎶','No live station','Start a room to synchronize its queue across devices.')}<div style="margin-top:21px">${btn('navigate',`Browse original beats ${icon('arrow')}`,'brick-btn','data-view="lab"')}</div></section><aside class="panel content-panel"><h3 class="panel-title">Add a sound link</h3><p class="text-muted">Use a video link for the official YouTube player, or a direct HTTPS audio file with playback permission.</p><form id="trackForm"><label class="input-label" for="linkTitle">Track name</label><input id="linkTitle" class="field" maxlength="80" placeholder="Something good" required><label class="input-label" for="linkUrl">YouTube or direct audio URL</label><input id="linkUrl" type="url" class="field" placeholder="https://..." required>${btn('add-track-link',`${icon('plus')} Add to queue`,'brick-btn join-join',!r||!hasRights()?'disabled':'')}</form><div class="queue-local-import"><div><strong>Your music, offline.</strong><p>Import songs from your Android phone and play them in My Crate. Files stay private to your device; they are not added to the shared station queue.</p></div>${btn('import-files',`${icon('upload')} Add local music`,'brick-btn small secondary')}</div><div class="notice" style="margin-top:20px"><strong>Play fair.</strong> YouTube stays inside its official video player. The app never extracts or rebroadcasts audio. Direct audio files require rights and host permission.</div>${r&&!hasRights()?`<p class="micro-copy">Only the host and approved admins may add tracks.</p>`:''}</aside></div>`}
function memberCard(m,i){const mine=m.id===state.identity,request=state.room?.requests?.includes(m.id);return `<div class="crew-person"><span class="crew-avatar alt${i%3===0?'0':i%3}" >${esc(m.name.charAt(0)).toUpperCase()}</span><div class="crew-body"><strong>${esc(m.name)} ${mine?'<span style="color:var(--muted)">(you)</span>':''}</strong><span>${request?'✳ Requests admin access':'Making waves together'}</span></div><span class="crew-role ${m.role}">${esc(m.role)}</span>${state.role==='host'&&m.role!=='host'?`<button class="icon-btn" aria-label="Hold to ${m.role==='admin'?'revoke':'grant'} admin" title="Press and hold to ${m.role==='admin'?'revoke':'grant'} admin" data-holdrole="${esc(m.id)}" data-grant="${m.role!=='admin'}" style="touch-action:none">${icon('settings')}</button>`:''}</div>`}
function crewView(){const r=state.room;return `<div class="overline">Better when we click</div><h1 class="page-title">Meet your crew.</h1><p class="page-sub">Every station needs good people. Chat in real time, throw reactions, and build the queue together. Hosts manage permissions.</p><div class="two-col" style="margin-top:27px"><section class="panel content-panel"><div class="flex-between"><h3 class="panel-title">Builders in the room ${r?`(${r.members.length})`:''}</h3><span class="soft-pill">${r?'● Live':'○ Offline'}</span></div>${r?`<div class="crew-list">${r.members.map(memberCard).join('')}</div>${state.role==='listener'?`<div style="margin-top:20px">${btn('request-admin',`${icon('plus')} Request admin controls`,'brick-btn secondary')}</div>`:''}${state.role==='host'?`<p class="micro-copy">Press and hold the gear next to a member to grant or revoke admin status. Admins cannot end the station or grant admin to others.</p>`:''}`:empty('👥','Your crew is waiting','Create or join a room to meet your listeners.')}<div style="margin-top:20px">${!r?btn('open-host',`${icon('plus')} Start a room`):''}</div></section><section class="panel content-panel"><h3 class="panel-title">Room chat</h3>${r?`<div class="chat-messages" id="chatHistory">${r.chat.length?r.chat.map(m=>`<div class="chat-msg ${m.from===state.identity?'me':''}"><div class="bubble"><small>${esc(m.name)}</small><p>${esc(m.text)}</p><time>${new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div></div>`).join(''):`<div class="empty-state" style="padding:48px 10px">🫧<p>Say something. Start a vibe.</p></div>`}</div><form id="chatForm" class="chat-compose"><input id="chatText" class="field" maxlength="400" placeholder="Say something..." autocomplete="off" aria-label="Chat message" required><button class="brick-btn small" type="submit">Send ${icon('arrow')}</button></form><div class="reaction-buttons">${['🧱','🔥','💜','🎵','⚡','✨'].map(e=>`<button type="button" class="reaction-btn" data-action="react" data-emoji="${esc(e)}" aria-label="React ${e}">${e}</button>`).join('')}</div>`:empty('💬','No conversation yet','Your station chat will appear here once you join a room.')}</section></div>`}
function crateView(){const r=state.room;return `<div class="overline">Songs you actually own</div><h1 class="page-title">My Crate.</h1><p class="page-sub">Keep a personal offline library of audio files on this device, and link Google Drive folders to a station. Your uploaded files are not sent to our server.</p><div class="two-col" style="margin-top:26px"><section><div class="upload-zone" id="dropZone"><div class="upload-illustration">${icon('upload')}</div><h3>Drop tracks into your crate.</h3><p>Import your MP3, M4A, WAV or other compatible audio files.<br>Stored locally on this device, available offline.</p>${btn('import-files',`${icon('upload')} Add music from device`)}</div>${section('Your offline tracks',`${state.localFiles.length} track${state.localFiles.length===1?'':'s'} stored on this device`)}${state.localFiles.length?`<div class="local-list">${state.localFiles.map(f=>`<div class="panel local-file"><div class="album-round">♫</div><main><strong>${esc(f.name)}</strong><small>${(f.size/1024/1024).toFixed(1)} MB · ${esc(f.type||'audio')}</small></main>${ibtn('local-play','play','Play local audio','icon-btn',`data-id="${esc(f.id)}"`)}${ibtn('local-delete','close','Delete local audio','icon-btn',`data-id="${esc(f.id)}"`)}</div>`).join('')}</div>`:empty('🎼','Your crate is empty','Import a track to start your offline collection.')}</section><aside class="panel content-panel"><h3 class="panel-title">Google Drive connections</h3><p class="text-muted">You can save multiple shared folder links to your station. The folders are available for participants to open directly.</p>${r?`<div class="queue-list">${r.folders.map(f=>`<div class="folder-row"><div class="folder-icon">📁</div><div class="file-main"><strong>${esc(f.title)}</strong><small>Shared Google Drive folder</small></div><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a>${hasRights()?ibtn('folder-remove','close','Remove folder','icon-btn',`data-id="${esc(f.id)}"`):''}</div>`).join('')}${!r.folders.length?`<p class="micro-copy">No folders connected yet.</p>`:''}</div><form id="folderForm"><label class="input-label" for="folderTitle">Folder nickname</label><input class="field" id="folderTitle" maxlength="45" placeholder="e.g. Weekend mixes"><label class="input-label" for="folderUrl">Shared folder link</label><input class="field" id="folderUrl" type="url" placeholder="https://drive.google.com/drive/folders/..." required><button class="brick-btn join-join" type="submit" ${hasRights()?'':'disabled'}>${icon('plus')} Save folder link</button></form>`:empty('📁','Join a room first','Shared Drive links belong to a live station.')}<div class="notice warn" style="margin-top:20px"><strong>Good to know:</strong> Pasting a Drive folder URL cannot automatically scan or stream its audio contents. Directly syncing folder music requires permission plus the Google Drive API or an accessible folder manifest.</div></aside></div>`}
function settingsView(){return `<div class="overline">Make it yours</div><h1 class="page-title">The little details.</h1><p class="page-sub">Tune your playground. Your theme and name stay on this device.</p><div class="two-col" style="margin-top:26px"><section class="panel content-panel"><h3 class="panel-title">Your builder profile</h3><form id="settingsForm"><label for="settingsName" class="input-label">Nickname</label><input class="field" maxlength="25" id="settingsName" value="${esc(state.name)}" required><label for="settingsUrl" class="input-label">Live server WebSocket URL</label><input class="field" id="settingsUrl" spellcheck="false" placeholder="wss://your-server.example.com/socket" value="${esc(state.serverUrl)}"><p class="micro-copy">For multiplayer on different devices, enter a deployed WebSocket server address. When running this site on its own Node server, the address is prefilled.</p><button type="submit" class="brick-btn" style="margin-top:15px">${icon('check')} Save settings</button></form><h3 class="panel-title" style="margin-top:31px">Pick your plastic</h3><div style="display:flex;gap:10px">${btn('set-slate','🌙 Slate','brick-btn '+(state.theme==='slate'?'':'secondary'))}${btn('set-paper','☀️ Paper','brick-btn '+(state.theme==='paper'?'':'secondary'))}</div></section><aside class="panel content-panel"><h3 class="panel-title">Built for real music lovers</h3><div class="notice"><strong>What works:</strong> Shared PIN rooms, queue updates, chat, admin roles and synchronized original synth beats, when the server is online. You can play personal audio locally and offline.</div><div class="notice warn" style="margin-top:14px"><strong>Still a preview:</strong> Google Drive folder indexing, rebroadcasting copyrighted music, cross-device local-file streaming, automatic YouTube synchronization and push-to-talk are not implemented. Production needs hosted infrastructure, tests, security hardening, and rights clearance.</div><p class="micro-copy" style="margin-top:19px">Edition 03 — BRICKS · Built with Web Audio, IndexedDB, WebSockets, CSS 3D and an absurd amount of plastic joy.</p>${state.room?`<div style="margin-top:16px">${btn('leave',`Leave station`,'brick-btn secondary')}</div>`:''}</aside></div>`}
function renderDock(){const dock=$('#playerDock');let beat=null,t=null,playing=false,desc='',name='';
 if(state.room){t=selected();if(!t){dock.innerHTML='';return}const meta=trackMeta(t);name=meta?.title||t.title;desc=`${meta?.artist||'Shared audio'} · LIVE STATION`;playing=roomPlaying();beat=meta}
 else if(state.localTrackId){const f=state.localFiles.find(x=>x.id===state.localTrackId);if(!f){dock.innerHTML='';return}name=f.name;desc='MY CRATE · LOCAL AUDIO';playing=state.localAudio&&!state.localAudio.paused;beat={shade:'mint'}}
 else if(state.solo.track){beat=BEATS.find(x=>x.id===state.solo.track);if(!beat){dock.innerHTML='';return}name=beat.title;desc='SOUND LAB · ORIGINAL';playing=state.solo.playing}
 else {dock.innerHTML='';return}
 dock.innerHTML=`<div class="dock-card"><div class="dock-art">${art(beat?.shade||'peach')}</div><div class="dock-info"><strong>${esc(name)}</strong><small>${esc(desc)}</small></div><div class="dock-progress"><span id="dockFill"></span></div><div class="dock-controls">${btn('navigate',`${icon('music')}`,'','data-view="home" style="border:0;background:var(--surface2);color:var(--text);width:34px;height:34px;display:grid;place-items:center;border-radius:10px"')}${ibtn('dock-play',playing?'pause':'play',playing?'Pause':'Play','primary',state.room&&!hasRights()?'disabled':'')}</div></div>`;
}
function renderModal(){const root=$('#modalRoot'),m=state.modal;if(!m){root.innerHTML='';return}let body='';
 if(m==='host')body=`<div class="modal-icon">🧱</div><h2>Build your station.</h2><p>Give your room a name. Your rotating four-digit PIN will be ready when the first brick clicks into place.</p><form id="hostForm"><label class="input-label" for="hostName">Your nickname</label><input class="field" maxlength="25" id="hostName" value="${esc(state.name)}" required><label class="input-label" for="hostRoom">Station name</label><input class="field" maxlength="36" id="hostRoom" placeholder="The Saturday Build" value="The Brickroom" required><div class="modal-footer"><button type="button" class="brick-btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="brick-btn">Build it ${icon('arrow')}</button></div></form>`;
 if(m==='link')body=`<div class="modal-icon">🎵</div><h2>Add a track.</h2><p>Only use music you have the right to share. YouTube runs in its official video player.</p><form id="trackForm"><label class="input-label" for="linkTitle">Title</label><input class="field" id="linkTitle" placeholder="My favorite track"><label class="input-label" for="linkUrl">HTTPS link</label><input class="field" id="linkUrl" type="url" placeholder="https://..." required><div class="modal-footer"><button type="button" class="brick-btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="brick-btn">Add track</button></div></form>`;
 if(m==='end')body=`<div class="modal-icon">✕</div><h2>End this station?</h2><p>Everyone in the room will be disconnected and its temporary queue and chat will disappear.</p><div class="modal-footer">${btn('close-modal','Keep building','brick-btn secondary')}${btn('end-room','End the room','brick-btn')}</div>`;
 if(m==='video'){const t=selected();body=t?.kind==='youtube'?`<h2>${esc(t.title)}</h2><p>Official YouTube embedded player. Each participant controls video playback separately.</p><div style="aspect-ratio:16/9;overflow:hidden;border-radius:14px;background:#090a13"><iframe style="width:100%;height:100%;border:0" allow="accelerometer;autoplay;encrypted-media;gyroscope;picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube-nocookie.com/embed/${esc(t.videoId)}"></iframe></div><p><a href="${esc(t.url)}" target="_blank" rel="noopener noreferrer" style="color:var(--coral)">Open on YouTube ↗</a></p>`:`<h2>No video selected</h2>`}
 root.innerHTML=`<div class="modal-backdrop" data-action="close-modal" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(m)} dialog"><button class="icon-btn close-modal" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${body}</section></div>`;
}
function toast(message,danger=false){const root=$('#toastRoot'),el=document.createElement('div');el.className='toast'+(danger?' danger':'');el.innerHTML=`<span class="toast-check">${danger?'!':'✓'}</span><span>${esc(message)}</span>`;root.append(el);setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(-20px)';setTimeout(()=>el.remove(),300)},3100)}
function fling(emoji){const el=document.createElement('span');el.className='reaction-fly';el.textContent=emoji;el.style.right=15+Math.random()*65+'%';el.style.animationDelay=Math.random()*.12+'s';$('#reactionRoot').appendChild(el);setTimeout(()=>el.remove(),2400)}
function send(type,payload={}){if(state.socket?.readyState===WebSocket.OPEN){state.socket.send(JSON.stringify({type,...payload}));return true}toast('Connect to a live station first',true);return false}
function connect(type,payload){if(state.connecting)return;let url=state.serverUrl.trim();if(!url){toast('Set a WebSocket server address in Settings',true);navigate('settings');return}try{if(/^https?:\/\//.test(url))url=url.replace(/^http/,'ws');if(!/^wss?:\/\//.test(url))throw Error('Invalid server address');url=new URL(url);if(!url.pathname||url.pathname==='/')url.pathname='/socket';}catch{toast('Enter a valid WebSocket URL',true);navigate('settings');return}
 state.connecting=true;let ws;try{ws=new WebSocket(url.toString())}catch{state.connecting=false;toast('Unable to open the connection',true);return}state.socket=ws;toast('Connecting your bricks…');
 ws.onopen=()=>{state.connecting=false;state.connected=true;ws.send(JSON.stringify({type,...payload}));syncClock()};
 ws.onmessage=e=>{let msg;try{msg=JSON.parse(e.data)}catch{return}
  if(msg.type==='joined'){state.room=msg.room;state.identity=msg.id;state.role=msg.role;state.modal=null;state.solo.playing=false;state.localAudio?.pause();state.localTrackId=null;state.clockOffset=msg.room.serverTime-Date.now();navigate('home');toast('Connected. Welcome to the crew!');applyAudio();return}
  if(msg.type==='state'){state.room=msg.room;state.clockOffset=msg.room.serverTime-Date.now();render();applyAudio();return}
  if(msg.type==='role'){state.role=msg.role;toast(msg.role==='admin'?'You have admin controls now!':'Your admin controls were revoked');render();return}
  if(msg.type==='reaction'){fling(msg.emoji);return}
  if(msg.type==='pong'){const elapsed=Date.now()-msg.echo;if(elapsed<5000){state.clockOffset=msg.serverTime-(msg.echo+elapsed/2)}return}
  if(msg.type==='ended'){toast('This station has ended');leave(false);return}
  if(msg.type==='error'){toast(msg.message,true);return}
 };
 ws.onerror=()=>{if(!state.connected)toast('Unable to reach the station server',true)};
 ws.onclose=()=>{state.connecting=false;state.connected=false;if(state.socket!==ws)return;if(state.room){state.room=null;state.identity=null;state.role=null;engine.stop();render();toast('Station connection closed',true)}};
}
function syncClock(){if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'ping',time:Date.now()}))}
setInterval(syncClock,15000);
function leave(closeSocket=true){if(closeSocket)state.socket?.close();state.socket=null;state.room=null;state.role=null;state.identity=null;state.connected=false;state.modal=null;engine.stop();navigate('home')}
function applyAudio(){if(state.room){const t=selected();engine.sync(t,roomPlayback(),state.clockOffset)}else if(state.solo.track){engine.sync({kind:'beat',beat:state.solo.track,id:state.solo.track},{trackId:state.solo.track,playing:state.solo.playing,at:state.solo.at,offsetMs:state.solo.offsetMs},0)}else engine.sync(null,null,0)}
async function enableSound(){const ok=await engine.enable();state.soundEnabled=ok;if(ok){state.localAudio?.play().catch(()=>{});applyAudio();toast('Sound is on. Let’s build!');render()}else toast('Could not start audio on this device',true)}
async function startSolo(id){if(!BEATS.some(b=>b.id===id))return;if(state.room){toast('You are in a live room — add this beat to its queue to play it');return;}state.localAudio?.pause();state.localTrackId=null;state.solo.track=id;state.solo.playing=true;state.solo.offsetMs=0;state.solo.at=Date.now()+80;if(!state.soundEnabled)await enableSound();applyAudio();render();toast(`Playing ${BEATS.find(b=>b.id===id)?.title}`)}
function toggleSolo(){if(state.localTrackId){if(!state.localAudio)return;state.localAudio.paused?state.localAudio.play().catch(()=>toast('Tap to enable sound',true)):state.localAudio.pause();renderDock();return}if(!state.solo.track)return;state.solo.offsetMs=soloPosition();state.solo.at=Date.now()+80;state.solo.playing=!state.solo.playing;applyAudio();renderDock();if(state.view==='home')render()}
function playRoom(action){const r=state.room,t=selected();if(!r||!t||!hasRights())return;let next=t;
 if(action==='next'||action==='prev'){const ix=r.queue.findIndex(q=>q.id===t.id);next=r.queue[(ix+(action==='next'?1:-1)+r.queue.length)%r.queue.length]||t}
 send('playback',{trackId:next.id,playing:action==='toggle-room'?!r.playback.playing:true,offsetMs:action==='toggle-room'?positionMs():0})}
function handleClicks(event){const el=event.target.closest('[data-action]');if(!el)return;if(el.tagName==='A'&&el.dataset.action!=='navigate')return;const a=el.dataset.action;
 if(a==='close-modal'&&el.classList.contains('modal-backdrop')&&event.target!==el)return;
 if(a==='navigate'&&el.tagName==='A')event.preventDefault();
 const id=el.dataset.id,beat=el.dataset.beat;
 switch(a){
 case 'navigate':navigate(el.dataset.view||'home');break;
 case 'theme':state.theme=state.theme==='slate'?'paper':'slate';save();render();break;
 case 'set-paper':state.theme='paper';save();render();break;
 case 'set-slate':state.theme='slate';save();render();break;
 case 'open-host':state.modal='host';renderModal();break;
 case 'open-end':state.modal='end';renderModal();break;
 case 'open-video':state.modal='video';renderModal();break;
 case 'close-modal':state.modal=null;renderModal();break;
 case 'end-room':send('end');break;
 case 'enable-audio':enableSound();break;
 case 'filter':state.filter=el.dataset.filter;render();break;
 case 'solo-beat':startSolo(beat);break;
 case 'favorite':{const f=state.soloFavorites;f.has(beat)?f.delete(beat):f.add(beat);save();render();break}
 case 'add-beat':{const b=BEATS.find(b=>b.id===beat);if(b&&hasRights()){send('queue-add',{track:{kind:'beat',beat:b.id,title:b.title}});toast('Another brick in the queue!')}break}
 case 'toggle-room':playRoom('toggle-room');break;
 case 'dock-play':state.room?playRoom('toggle-room'):toggleSolo();break;
 case 'next':case 'prev':playRoom(a);break;
 case 'select-track':{const t=state.room?.queue.find(t=>t.id===id);if(t)send('playback',{trackId:t.id,playing:true,offsetMs:0});break}
 case 'queue-remove':send('queue-remove',{trackId:id});break;
 case 'queue-up':case 'queue-down':send('queue-move',{trackId:id,direction:a==='queue-up'?-1:1});break;
 case 'copy-pin':if(state.room){navigator.clipboard?.writeText(state.room.pin).then(()=>toast('Station PIN copied')).catch(()=>toast(`PIN: ${state.room.pin}`));}break;
 case 'request-admin':send('request-admin');toast('Admin request sent');break;
 case 'react':send('react',{emoji:el.dataset.emoji});break;
 case 'add-track-link':{const form=el.closest('form');if(form)submitTrack(form);break}
 case 'import-files':{const picker=$('#audioImport');if(!picker){toast('Audio picker unavailable',true);break}picker.click();break}
 case 'local-play':playLocal(id);break;
 case 'local-delete':deleteLocal(id);break;
 case 'folder-remove':send('folder-remove',{id});break;
 case 'leave':leave();break;
 }
}
function submitTrack(form){if(!state.room||!hasRights())return;const title=form.querySelector('#linkTitle')?.value.trim(),url=form.querySelector('#linkUrl')?.value.trim();if(!url){toast('Paste a link first',true);return}let u;try{u=new URL(url);if(u.protocol!=='https:')throw Error()}catch{toast('A valid HTTPS link is required',true);return}const yt=['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname.toLowerCase());const track={kind:yt?'youtube':'audio',title:title||'New track',url};send('queue-add',{track});state.modal=null;renderModal();toast('Track submitted to queue');form.reset()}
function submitForm(e){const form=e.target;if(!form?.id)return;e.preventDefault();switch(form.id){
 case 'joinForm':{const name=form.querySelector('#joinName').value.trim()||'Listener',pin=form.querySelector('#joinPin').value.replace(/\D/g,'').slice(0,4);if(pin.length!==4){toast('PIN needs four digits',true);return}state.name=name;state.joinPin=pin;save();connect('join',{name,pin});break}
 case 'hostForm':{state.name=form.querySelector('#hostName').value.trim()||'Host';const roomName=form.querySelector('#hostRoom').value.trim()||'The Brickroom';save();connect('create',{name:state.name,roomName});break}
 case 'chatForm':{const box=form.querySelector('#chatText');if(box.value.trim()){send('chat',{text:box.value.trim()});box.value=''}break}
 case 'trackForm':submitTrack(form);break;
 case 'folderForm':{send('folder-add',{title:form.querySelector('#folderTitle').value.trim(),url:form.querySelector('#folderUrl').value.trim()});form.reset();break}
 case 'settingsForm':{state.name=form.querySelector('#settingsName').value.trim()||'Builder';state.serverUrl=form.querySelector('#settingsUrl').value.trim();save();toast('Settings saved. Studs aligned!');render();break}
}}
let holdTimer=null,holdTriggered=false;
function startHold(e){const btn=e.target.closest('[data-holdrole]');if(!btn||state.role!=='host')return;holdTriggered=false;clearTimeout(holdTimer);btn.style.background='var(--coral)';btn.style.transform='scale(.9)';holdTimer=setTimeout(()=>{holdTriggered=true;send('role',{memberId:btn.dataset.holdrole,grant:btn.dataset.grant==='true'});toast(btn.dataset.grant==='true'?'Admin access granted':'Admin access revoked');btn.style.background='';btn.style.transform=''},620)}
function cancelHold(e){clearTimeout(holdTimer);const btn=e.target.closest?.('[data-holdrole]');if(btn){btn.style.background='';btn.style.transform=''}}
function updateProgress(){const dock=$('#dockFill');const el=$('[data-progress]'),elapsed=$('[data-elapsed]'),pin=$('#pinSeconds'),pinProg=$('#pinProgress');
 if(state.room){const t=selected(),meta=trackMeta(t),time=positionMs()/1000;const dur=(meta?.duration||180);const progress=t?.kind==='beat'?((time%dur)/dur*100):Math.min(100,time/dur*100);if(el)el.style.width=progress+'%';if(dock)dock.style.width=progress+'%';if(elapsed)elapsed.textContent=formatTime(time);if(pin)pin.textContent=Math.max(0,Math.ceil((state.room.pinExpires-serverNow())/1000))+'s';if(pinProg)pinProg.style.width=(Math.max(0,state.room.pinExpires-serverNow())/120000*100)+'%';}
 else if(state.solo.track){const dur=BEATS.find(b=>b.id===state.solo.track)?.duration||120;if(dock)dock.style.width=((soloPosition()/1000%dur)/dur*100)+'%'}
 else if(state.localAudio&&dock&&Number.isFinite(state.localAudio.duration))dock.style.width=(state.localAudio.currentTime/state.localAudio.duration*100)+'%';
}
let animateHandle=0;
function visualLoop(){const c=$('#visualizer');if(c){const dpr=Math.min(2,window.devicePixelRatio||1),width=c.clientWidth,height=c.clientHeight;if(width&&height){if(c.width!==Math.round(width*dpr)){c.width=Math.round(width*dpr);c.height=Math.round(height*dpr)}const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.scale(dpr,dpr);const levels=engine.levels(),spacing=width/levels.length,playing=state.room?.playback?.playing;levels.forEach((l,i)=>{const seed=playing?l:Math.max(.1,Math.sin(Date.now()/850+i*.6)*.13+.22),h=Math.max(4,Math.min(height-2,seed*(height-4)));ctx.fillStyle=i%4===0?'#ffd56d':i%3===0?'#a99cfe':'#ff8065';const x=i*spacing+spacing*.15;ctx.beginPath();ctx.roundRect(x,(height-h)/2,Math.max(2,spacing*.66),h,Math.min(4,spacing*.24));ctx.fill()});ctx.restore()}}
 animateHandle=requestAnimationFrame(visualLoop)}
/* Local audio stays in IndexedDB; no files are uploaded by this interface. */
let dbPromise;
function db(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('Offline audio storage is unsupported on this device'));return}const req=indexedDB.open('chimpanzee-bricks-local',1);req.onupgradeneeded=()=>req.result.createObjectStore('tracks',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function dbAction(method,arg){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('tracks',method==='get'||method==='getAll'?'readonly':'readwrite'),store=tx.objectStore('tracks');const req=store[method](arg);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function refreshLocal(){try{const list=await dbAction('getAll');state.localFiles=list.map(({blob,...m})=>m).sort((a,b)=>b.added-a.added);if(state.view==='crate')render()}catch(e){console.info('Local store:',e.message)}}
async function importAudio(files){let added=0;for(const f of [...files]){if(!f.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|aac|flac|opus)$/i.test(f.name))continue;if(f.size>60*1024*1024){toast(`${f.name.slice(0,20)} is larger than 60 MB`,true);continue}try{await dbAction('put',{id:crypto.randomUUID(),name:f.name.replace(/\.[^.]+$/,''),type:f.type||'audio',size:f.size,added:Date.now(),blob:f});added++}catch(e){toast('Storage may be full or unavailable',true);break}}
 if(added){await refreshLocal();navigate('crate');toast(`Added ${added} track${added===1?'':'s'} to My Crate — ready to play offline!`)}else if(files?.length){toast('No supported audio files selected',true)}$('#audioImport').value=''}
async function playLocal(id){try{const f=await dbAction('get',id);if(!f){toast('Could not find that track',true);return}engine.stop();state.solo.track=null;state.solo.playing=false;if(state.localAudio){state.localAudio.pause();state.localAudio.src=''}if(state.localBlobUrl)URL.revokeObjectURL(state.localBlobUrl);const url=URL.createObjectURL(f.blob);const audio=new Audio(url);audio.volume=engine.level;audio.onended=()=>{state.localTrackId=null;renderDock()};state.localBlobUrl=url;state.localAudio=audio;state.localTrackId=id;await audio.play();renderDock();toast(`Playing ${f.name}`)}catch(e){toast('Could not play this audio format',true)}}
async function deleteLocal(id){try{await dbAction('delete',id);if(state.localTrackId===id){state.localAudio?.pause();state.localTrackId=null;if(state.localBlobUrl)URL.revokeObjectURL(state.localBlobUrl)}await refreshLocal();renderDock();toast('Removed from your crate')}catch{toast('Could not remove this file',true)}}
window.addEventListener('click',handleClicks);
window.addEventListener('submit',submitForm);
function tactileBurst(e){const btn=e.target.closest('button');if(!btn||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=btn.getBoundingClientRect();const x=r.left+r.width/2,y=r.top+r.height/2;const colors=['#ff775e','#ffd56d','#79e2c4','#ae9efe'];const count=btn.classList.contains('brick-btn')?8:3;for(let i=0;i<count;i++){const a=Math.PI*2*i/count+Math.random()*.5,dist=35+Math.random()*45,s=document.createElement('i');s.className='stud-pop';s.style.left=x+'px';s.style.top=y+'px';s.style.setProperty('--pop-color',colors[i%colors.length]);s.style.setProperty('--pop-size',Math.round(7+Math.random()*6)+'px');s.style.setProperty('--pop-x',Math.round(Math.cos(a)*dist)+'px');s.style.setProperty('--pop-y',Math.round(Math.sin(a)*dist-15)+'px');s.style.setProperty('--pop-rot',(Math.random()*360)+'deg');document.body.appendChild(s);setTimeout(()=>s.remove(),850)}}
window.addEventListener('pointerdown',tactileBurst);
window.addEventListener('pointerdown',startHold);
window.addEventListener('pointerup',cancelHold);
window.addEventListener('pointercancel',cancelHold);
window.addEventListener('contextmenu',e=>{if(e.target.closest('[data-holdrole]'))e.preventDefault()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;renderModal()}});
window.addEventListener('input',e=>{if(e.target.id==='volume'){engine.setVolume(e.target.value/100);const label=$('#volumeLabel');if(label)label.textContent=e.target.value+'%'}if(e.target.id==='joinPin'){state.joinPin=e.target.value.replace(/\D/g,'').slice(0,4);e.target.value=state.joinPin}});
$('#audioImport').addEventListener('change',e=>importAudio(e.target.files));
window.addEventListener('dragover',e=>{if(e.target.closest('#dropZone')){e.preventDefault();e.target.closest('#dropZone').classList.add('drag')}});
window.addEventListener('dragleave',e=>{e.target.closest('#dropZone')?.classList.remove('drag')});
window.addEventListener('drop',e=>{const zone=e.target.closest('#dropZone');if(zone){e.preventDefault();zone.classList.remove('drag');importAudio(e.dataTransfer.files)}});
setInterval(updateProgress,260);
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')applyAudio()});
window.addEventListener('pointermove',e=>{const hero=e.target.closest('.welcome-hero');if(!hero)return;const r=hero.getBoundingClientRect();const dx=(e.clientX-r.left)/r.width-.5;hero.style.setProperty('--sculpture-tilt',(dx*12).toFixed(1)+'deg')},{passive:true});
engine.setVolume(.75);
render();refreshLocal();visualLoop();
setTimeout(()=>{$('#splash').classList.add('done');state.introDone=true;setTimeout(()=>$('#splash')?.remove(),900)},2600);
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});